"""The client address of a request (docs/ratelimit.md, section 7)."""

import ipaddress


def parse_address(text):
    """An address from an entry (section 7.3), or None."""
    t = text
    if t.startswith("["):
        end = t.find("]")
        if end < 0:
            return None
        rest = t[end + 1:]
        t = t[1:end]
        if rest:
            if not (rest.startswith(":") and rest[1:].isascii() and rest[1:].isdigit()):
                return None
        if ":" not in t:
            return None
    elif t.count(":") == 1:
        t, port = t.split(":")
        if not (port.isascii() and port.isdigit()):
            return None
    if not t or "%" in t or "/" in t or not t.isascii() or t != t.strip():
        return None
    try:
        a = ipaddress.ip_address(t)
    except ValueError:
        return None
    if a.version == 6 and a.ipv4_mapped is not None:
        a = a.ipv4_mapped
    return a


def in_any(addr, nets) -> bool:
    return addr is not None and any(addr in n for n in nets)


def client_address(request, trusted):
    """The client address as an ipaddress object, or the raw peer string if it is not an address."""
    peer = parse_address(request.peer)
    if peer is None:
        return request.peer
    if not in_any(peer, trusted):
        return peer
    entries = []
    for v in request.headers.get_all("X-Forwarded-For"):
        entries.extend(e.strip(" \t") for e in v.split(","))
    if not entries:
        return peer
    right = peer
    for e in reversed(entries):
        a = parse_address(e)
        if a is None:
            return right
        if not in_any(a, trusted):
            return a
        right = a
    return parse_address(entries[0])


def client_key(addr) -> str:
    if isinstance(addr, str):
        return addr
    if addr.version == 4:
        return str(addr)
    return str(ipaddress.ip_network((addr, 64), strict=False))
