"""Stage 3: rate limiting (docs/ratelimit.md)."""

import math
from fractions import Fraction

from frontdoor.ratelimit.clientaddr import client_address, client_key, in_any
from frontdoor.ratelimit.state import new_state

NAME = "ratelimit"
INF = float("inf")


class State:
    def __init__(self, config):
        self.limits = config.section("limit") or []
        self.trusted = config.section("clients") or ()
        self.buckets = {}
        self.clock = None
        self.limited = {lim.name: 0 for lim in self.limits}


def setup(config):
    return State(config)


def _key(lim, ctx, client):
    vals = []
    for part in lim.key:
        if part == "tenant":
            v = ctx.tenant
        elif part == "client":
            v = client_key(client)
        elif part == "route":
            v = ctx.route.name
        elif part == "method":
            v = ctx.request.method.upper()
        else:
            raw = ctx.request.headers.get(part[len("header:"):])
            v = raw.strip(" \t") if raw is not None else None
        if v is None or v == "":
            return None
        vals.append(v)
    return tuple(vals)


def handle(ctx, st):
    if not st.limits:
        return None
    req = ctx.request
    now = req.ts_ms if st.clock is None else max(st.clock, req.ts_ms)
    st.clock = now
    client = client_address(req, st.trusted)
    caddr = client if not isinstance(client, str) else None
    method = req.method.upper()
    cover = []
    for lim in st.limits:
        if lim.routes is not None and ctx.route.name not in lim.routes:
            continue
        if lim.methods is not None and method not in lim.methods:
            continue
        if in_any(caddr, lim.exempt):
            continue
        key = _key(lim, ctx, client)
        if key is None:
            continue
